from __future__ import absolute_import

from selenium.common.exceptions import TimeoutException
from selenium.webdriver.common.by import By
from taf.selenium.sbts_fsm3.pages.modals import FceInstallationFailedModal
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel


class ConfigurationAutomationPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Configuration', 'Configuration Management', 'Configuration Automation']

    def __init__(self, driver):
        super(ConfigurationAutomationPage, self).__init__(driver)
        self._view_panel = ConfigurationAutomationPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def install_fce(self, file_path, select_plan=None):
        return self._view_panel.install_fce(file_path, select_plan)

    def calculate_based_on_configurations(self, feature="PDCCH", **kwargs):
        return self._view_panel.calculate_based_on_configurations(feature, **kwargs)

    def apply_all_configurations(self):
        return self._view_panel.apply_all_configurations()


class ConfigurationAutomationPageViewPanel(ViewPanel):
    _FCE_FILE_BUTTON_SCRIPT = "#install-fce input"
    _FCE_FILE_BUTTON_XPATH = '//*[@id="install-fce"]//input'
    _COVER_SCREEN = "//cem-loading-screen"

    _SELECT_PLAN_DROPDOWN = '//div[label[contains(text(), "Select plan")]]//p-dropdown'
    _SELECT_PLAN_OPTIONS = '//div[label[contains(text(), "Select plan")]]//ul//li//span[contains(text(), "{}")]'

    _FEATURE_DROPDOWN = '//div[label[contains(text(), "Feature")]]//p-dropdown'
    _FEATURE_OPTIONS = '//div[label[contains(text(), "Feature")]]//ul//li//span[contains(text(), "{}")]'
    _CALCULATE = '//cem-operation-button//span[contains(text(), "Calculate")]'
    _CALCULATE_INFO = '//blocks-configuration-automation-results//ot-instruction'
    _INSTALL_FCE_SUCCEED = 'FCE installation succeed'

    _APPLY_ALL = '//cem-operation-button[@*="Apply All"]//button'
    _APPLY_ALL_STATUS = '//cem-operation-button[@*="Apply All"]//ot-instruction'

    def __init__(self, driver):
        super(ConfigurationAutomationPageViewPanel, self).__init__(driver)

    def install_fce(self, file_path, select_plan=None, timeout=60):
        if select_plan:
            self.select_element_from_dropdown_list_by_text_and_click(select_plan,
                                                                     (By.XPATH, self._SELECT_PLAN_DROPDOWN),
                                                                     (By.XPATH,
                                                                      self._SELECT_PLAN_OPTIONS.format(select_plan)))

        self.load_file_from_hidden_button(self._FCE_FILE_BUTTON_SCRIPT,
                                          self._FCE_FILE_BUTTON_XPATH,
                                          file_path,
                                          timeout)

        modal = FceInstallationFailedModal(self.driver)
        try:
            modal.wait_until_fce_installation_failed_modal_appear(3)
            return modal.close()
        except TimeoutException:
            pass

        try:
            self.wait_for_text_present_in_attribute(self._COVER_SCREEN, "ng-reflect-visible", "true", timeout=3)
        except TimeoutException:
            pass

        self.wait_for_text_present_in_attribute(self._COVER_SCREEN, "ng-reflect-visible", "false")
        return self._INSTALL_FCE_SUCCEED

    def calculate_based_on_configurations(self, feature="PDCCH", timeout=60, **kwargs):
        elems = self.expand_dropdown_list_and_return_elements(
            (By.XPATH, self._FEATURE_DROPDOWN),
            (By.XPATH, self._FEATURE_OPTIONS.format(feature))
        )
        assert len(elems) == 1
        elems[0].click()
        self.click_enabled_element((By.XPATH, self._CALCULATE))

        self.wait_for_text_present_in_attribute(self._COVER_SCREEN, "ng-reflect-visible", "true")
        self.wait_for_text_present_in_attribute(self._COVER_SCREEN, "ng-reflect-visible", "false")

        self.wait_for_visibility_by_xpath(self._CALCULATE_INFO, timeout)
        return self.get_text_by_xpath(self._CALCULATE_INFO)

    def apply_all_configurations(self):
        try:
            self.click_enabled_element((By.XPATH, self._APPLY_ALL), 3)
        except TimeoutException:
            return ''

        return self.get_text_by_xpath(self._APPLY_ALL_STATUS)
